<template>
  <div class="operations">
    <workspace-heading section="资产与作业 / INSPECTION" title="健康巡检" description="独立检查当前健康情况，生成可导出的巡检报告。"/>
    <a-alert type="info" show-icon message="先选择检查内容与资产，再提交任务。巡检只读取配置；基线及补丁证据需要人工复核，不代表完整漏洞扫描。" />
    <a-tabs v-model:activeKey="tab">
      <a-tab-pane key="inspection" tab="健康巡检">
        <a-alert v-if="!store.getters.canOperate" type="info" message="当前账号可查看已有巡检报告。"/>
        <div v-if="store.getters.canOperate" class="profiles"><a-card v-for="(label,key) in profiles" :key="key" size="small" :class="{chosen:profile===key}" @click="profile=key"><a-radio :checked="profile===key">{{label}}</a-radio><p>{{profileHelp[key]}}</p></a-card></div>
        <a-form v-if="store.getters.canOperate" layout="vertical"><a-form-item label="报告信息（可选）"><a-space wrap><a-input v-model:value="reportTitle" placeholder="报告标题，例如：重要保障期间主机健康报告" style="width:360px"/><a-input v-model:value="reportRecipient" placeholder="报告接收方" style="width:220px"/><a-input v-model:value="reportPurpose" placeholder="巡检用途，例如：日常健康检查 / 保障巡检" style="width:360px"/></a-space></a-form-item><a-form-item label="额外检查（可选）"><a-space wrap><a-input v-model:value="services" placeholder="服务名，如 nginx,sshd（逗号分隔）" style="width:360px" /><a-input v-model:value="certificates" placeholder="证书绝对路径（逗号分隔）" style="width:420px" /></a-space></a-form-item></a-form>
        <a-space wrap class="toolbar"><a-input-search v-model:value="hostSearch" placeholder="筛选主机名称 / IP / 业务" style="width:280px" /><a-button @click="loadHosts">刷新资产</a-button><template v-if="store.getters.canOperate"><span>已选择 {{selected.length}} 台</span><a-button @click="selected=[]">清空选择</a-button><a-button :disabled="!selected.length" @click="submit('probe')">检测在线状态</a-button><a-button type="primary" :disabled="!selected.length" @click="submit('inspection')">开始巡检</a-button></template><a-button @click="goResults()">查看巡检报告</a-button></a-space>
        <a-table :data-source="filteredHosts" :columns="hostColumns" row-key="id" :pagination="{pageSize:10}" :scroll="{x:650}" :row-selection="store.getters.canOperate ? {selectedRowKeys:selected,onChange:keys=>selected=keys,preserveSelectedRowKeys:true} : undefined"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='connection_state'"><a-badge :color="record.connection_state==='reachable'?'green':record.connection_state==='unreachable'?'red':'gray'" :text="record.connection_state==='reachable'?'最近检测在线':record.connection_state==='unreachable'?'最近检测离线':'未检测'" /></template></template></a-table>
      </a-tab-pane>
      <a-tab-pane key="schedules" tab="定时检查">
        <a-alert type="info" message="每个计划独立选择主机和检查内容。间隔最少 15 分钟，默认停用；上轮未结束时跳过本轮，不积压补跑。编辑会重新计算下次执行时间；启用时保留尚未到期的首次执行时间。" />
        <a-space class="toolbar"><a-button v-if="store.getters.canOperate" type="primary" @click="editSchedule()">新建计划</a-button><a-button @click="refreshSchedules">刷新</a-button></a-space>
        <a-table :data-source="schedules" :columns="scheduleColumns" row-key="id" :scroll="{x:1100}"><template #bodyCell="{column,record}"><template v-if="column.key==='content'">{{kinds[record.kind]}} · {{profiles[record.options.profile]}}<br/><small>{{record.host_ids.length}} 台 / 每 {{record.interval_minutes}} 分钟</small></template><template v-if="column.key==='status'"><a-tag :color="record.enabled?'green':'default'">{{record.enabled?'已启用':'已停用'}}</a-tag><div>{{record.enabled?time(record.next_run):'启用后开始调度'}}</div></template><template v-if="column.key==='last'"><a v-if="record.last_task_id" @click="goTask(record.last_task_id)">#{{record.last_task_id}} {{states[record.last_status]}}</a><span v-else>尚未执行</span><div style="color:var(--danger)">{{record.last_error}}</div></template><template v-if="column.key==='action'&&store.getters.canOperate"><a-space wrap><a-button size="small" @click="editSchedule(record)">编辑</a-button><a-button size="small" @click="runSchedule(record)">立即检查</a-button><a-button size="small" @click="toggleSchedule(record)">{{record.enabled?'停用':'启用'}}</a-button><a-popconfirm title="删除计划？历史任务仍会保留" @confirm="deleteSchedule(record)"><a-button size="small" danger>删除</a-button></a-popconfirm></a-space></template></template></a-table>
      </a-tab-pane>
      <a-tab-pane key="templates" tab="命令模板">
        <a-alert type="info" message="模板是可重复使用的命令：选择模板 → 选择主机 → 填写参数 → 预览命令 → 确认执行。普通用户提交后仍需审批。" />
        <a-space class="toolbar"><a-button v-if="admin" type="primary" @click="newTemplate()">新建模板</a-button><a-button v-if="admin" @click="newTemplate(true)">用“服务状态查询”示例创建</a-button><a-button @click="loadTemplates">刷新</a-button></a-space>
        <a-table :data-source="templates" :columns="templateColumns" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.key==='command'"><code>{{record.cmd}}</code><div>{{record.description || '暂无用途说明'}}</div><small>{{record.parameters.length?record.parameters.length+' 个参数，执行时填写':'无需填写参数'}}</small></template><template v-if="column.key==='action'"><a-space><a-button v-if="admin" @click="editTemplate(record)">编辑 / 历史</a-button><a-button v-if="store.getters.canOperate" type="primary" @click="prepareRun(record)">使用模板</a-button></a-space></template></template></a-table>
      </a-tab-pane>

    </a-tabs>
    <a-modal v-model:open="scheduleOpen" :title="scheduleForm.id?'编辑定时检查':'新建定时检查'" width="850px" :confirm-loading="saving" @ok="saveSchedule">
      <a-form layout="vertical"><a-form-item label="计划名称" required><a-input v-model:value="scheduleForm.name" :maxlength="100" placeholder="例如：保障期间每日健康检查"/></a-form-item><a-form-item label="目标主机" required><a-select v-model:value="scheduleForm.host_ids" mode="multiple" show-search option-filter-prop="label" :options="hostOptions" placeholder="可搜索，多选，与其他标签页互不影响"/></a-form-item><a-row :gutter="16"><a-col :span="12"><a-form-item label="检查类型"><a-select v-model:value="scheduleForm.kind" :options="options({inspection:'只读巡检',probe:'SSH 端口在线检测'})"/></a-form-item></a-col><a-col :span="12"><a-form-item label="执行间隔"><a-select v-model:value="scheduleForm.interval_minutes" :options="[{value:15,label:'每 15 分钟'},{value:30,label:'每 30 分钟'},{value:60,label:'每小时'},{value:360,label:'每 6 小时'},{value:1440,label:'每天（间隔 24 小时）'},{value:10080,label:'每周（间隔 7 天）'},]"/></a-form-item></a-col></a-row><a-form-item label="自定义间隔（15～10080 分钟）"><a-input-number v-model:value="scheduleForm.interval_minutes" :min="15" :max="10080"/></a-form-item><template v-if="scheduleForm.kind==='inspection'"><a-form-item label="检查方案"><a-select v-model:value="scheduleForm.profile" :options="options(profiles)"/></a-form-item><a-form-item label="额外服务 / 证书"><a-input v-model:value="scheduleForm.services" placeholder="服务名，逗号分隔"/><a-input v-model:value="scheduleForm.certificates" placeholder="证书路径，逗号分隔"/></a-form-item></template><a-form-item label="首次执行时间（可选，留空为当前时间加间隔）"><a-input v-model:value="scheduleForm.first_run" type="datetime-local"/></a-form-item></a-form>
    </a-modal>
    <a-modal v-model:open="templateOpen" title="命令模板：用途、命令与参数" width="900px" :confirm-loading="saving" @ok="saveTemplate">
      <a-form layout="vertical"><a-form-item label="名称" required><a-input v-model:value="templateForm.name"/></a-form-item><a-form-item label="用途说明"><a-input v-model:value="templateForm.description" placeholder="说明查询什么、有无修改系统的行为"/></a-form-item><a-form-item label="分类" required><a-select v-model:value="templateForm.category" :options="categories.map(x=>({value:x.id,label:x.name}))"/><a-input-search v-model:value="categoryName" placeholder="也可输入新分类名称" enter-button="创建分类" @search="createCategory"/></a-form-item><a-form-item label="命令" required><a-textarea v-model:value="templateForm.cmd" :rows="3"/><small v-text="'例如 systemctl status {{service}} --no-pager。参数占位符独立放置，不加引号。'"/></a-form-item>
      <a-form-item label="执行时需要填写的参数（可选，最多 10 个）"><div v-for="(spec,i) in templateForm.parameters" :key="i" class="parameter"><a-input v-model:value="spec.name" placeholder="参数名，如 service"/><a-select v-model:value="spec.type" :options="[{value:'text',label:'文本'},{value:'integer',label:'整数'},{value:'enum',label:'下拉选项'}]" style="min-width:110px"/><a-input v-if="spec.type==='enum'" v-model:value="spec.choiceText" placeholder="可选值，逗号分隔"/><a-input v-model:value="spec.default" placeholder="默认值（可选）"/><a-button danger @click="templateForm.parameters.splice(i,1)">移除</a-button></div><a-button :disabled="templateForm.parameters?.length>=10" @click="templateForm.parameters.push({name:'',type:'text',choiceText:'',default:''})">添加参数</a-button></a-form-item></a-form>
      <a-collapse v-if="revisions.length"><a-collapse-panel v-for="r in revisions" :key="r.version" :header="`历史版本 ${r.version}`"><pre>{{r.command}}</pre><p>{{r.description}}</p></a-collapse-panel></a-collapse>
    </a-modal>
    <a-modal v-model:open="runOpen" :title="'使用模板：'+(runTarget?.name||'')" width="800px" ok-text="确认提交任务" :confirm-loading="saving" @ok="runTemplate">
      <a-form layout="vertical"><a-form-item label="目标主机" required><a-select v-model:value="runHosts" mode="multiple" show-search option-filter-prop="label" :options="hostOptions"/></a-form-item><a-form-item v-for="spec in runTarget?.parameters||[]" :key="spec.name" :label="spec.name" :required="spec.required!==false"><a-select v-if="spec.type==='enum'" v-model:value="parameters[spec.name]" :options="spec.choices.map(x=>({value:x,label:x}))" @change="preview=''"/><a-input v-else v-model:value="parameters[spec.name]" @change="preview=''"/></a-form-item></a-form><a-button @click="previewCommand">预览最终命令</a-button><pre class="evidence">{{preview||'填写参数后点击预览，检查实际执行的命令。'}}</pre><a-alert type="warning" message="请确认目标主机及命令影响。管理员确认后排队执行，普通用户需要审批；预览不会连接主机。"/>
    </a-modal>

  </div>
</template>
<script setup>
import WorkspaceHeading from '@/components/WorkspaceHeading.vue'
import {ref,computed,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import {useStore} from 'vuex'
import {message,Modal} from 'ant-design-vue'
import api from '@/api'
import {kinds,profiles,states,color,options,time} from '@/utils/ops'
const router=useRouter(),store=useStore(),admin=computed(()=>store.getters.userInfo?.is_superuser)
const reportTitle=ref(''),reportRecipient=ref(''),reportPurpose=ref('')
const tab=ref('inspection'),hosts=ref([]),selected=ref([]),hostSearch=ref(''),profile=ref('health'),services=ref(''),certificates=ref(''),saving=ref(false)
const schedules=ref([]),scheduleOpen=ref(false),scheduleForm=ref({}),templates=ref([]),categories=ref([])
const templateOpen=ref(false),templateForm=ref({parameters:[]}),revisions=ref([]),categoryName=ref(''),runOpen=ref(false),runTarget=ref(null),parameters=ref({}),runHosts=ref([]),preview=ref('')
const profileHelp={health:'CPU、内存、磁盘、负载及系统版本',baseline:'资源健康 + SSH 策略、权限、账号、时间同步及补丁缓存复核',acceptance:'安全基线 + 自定义服务与证书，保存验收证据'}
const hostOptions=computed(()=>hosts.value.map(h=>({value:h.id,label:`${h.name} · ${h.ip_addr}`})))
const filteredHosts=computed(()=>hosts.value.filter(h=>`${h.name} ${h.ip_addr} ${h.business}`.toLowerCase().includes(hostSearch.value.toLowerCase())))
const hostColumns=[{title:'名称',dataIndex:'name'},{title:'地址',dataIndex:'ip_addr'},{title:'业务',dataIndex:'business'},{title:'在线状态',dataIndex:'connection_state'}]
const scheduleColumns=[{title:'计划名称',dataIndex:'name'},{title:'检查内容',key:'content'},{title:'状态 / 下次执行',key:'status'},{title:'最近执行',key:'last'},{title:'操作',key:'action'}]
const templateColumns=[{title:'名称',dataIndex:'name'},{title:'版本',dataIndex:'version'},{title:'分类',dataIndex:'category_name'},{title:'命令与用途',key:'command'},{title:'操作',key:'action'}]
const split=s=>(s||'').split(/[,，\n]/).map(x=>x.trim()).filter(Boolean)
const checkOptions=(p,s,c)=>({profile:p,services:split(s),certificates:split(c)})
function goTask(id){router.push({name:'TaskCenter',query:{task:String(id)}})}
function goResults(){router.push({name:'TaskCenter',query:{kind:'inspection'}})}
async function loadHosts(){hosts.value=(await api.get('/host/')).data}
function submit(kind){Modal.confirm({okText:'确认',cancelText:'取消',title:kind==='probe'?'检测所选主机在线状态':'提交只读巡检',content:`已选 ${selected.value.length} 台；不会修改系统配置。`,onOk:async()=>{const {data}=await api.post('/mtask/tasks',{kind,host_ids:selected.value,options:{...checkOptions(profile.value,services.value,certificates.value),report_title:reportTitle.value,recipient:reportRecipient.value,purpose:reportPurpose.value},confirmed:true});goTask(data.id)}})}
async function refreshSchedules(){schedules.value=(await api.get('/mtask/schedules')).data}
function editSchedule(row){scheduleForm.value=row?{...row,host_ids:[...row.host_ids],profile:row.options.profile,services:(row.options.services||[]).join(','),certificates:(row.options.certificates||[]).join(','),first_run:''}:{name:'',host_ids:[],kind:'inspection',profile:'health',services:'',certificates:'',interval_minutes:60,first_run:''};scheduleOpen.value=true}
async function saveSchedule(){const f=scheduleForm.value;if(!f.name.trim()||!f.host_ids.length){message.warning('请填写名称并选择主机');return}saving.value=true;try{const body={name:f.name,host_ids:f.host_ids,kind:f.kind,interval_minutes:f.interval_minutes,options:checkOptions(f.profile,f.services,f.certificates)};if(f.first_run)body.next_run=new Date(f.first_run).toISOString();if(f.id)await api.patch(`/mtask/schedules/${f.id}`,body);else await api.post('/mtask/schedules',body);scheduleOpen.value=false;await refreshSchedules();message.success(f.id?'计划已更新':'计划已保存，启用后开始调度')}finally{saving.value=false}}
function toggleSchedule(row){Modal.confirm({okText:'确认',cancelText:'取消',title:row.enabled?'停用计划':'启用周期检查',content:`${row.host_ids.length} 台，每 ${row.interval_minutes} 分钟。`,onOk:async()=>{await api.patch(`/mtask/schedules/${row.id}`,{enabled:!row.enabled});await refreshSchedules()}})}
function runSchedule(row){Modal.confirm({okText:'确认',cancelText:'取消',title:'立即执行一次只读检查',content:'不改变计划的启用状态及下一次执行时间。',onOk:async()=>{const {data}=await api.post(`/mtask/schedules/${row.id}`,{confirmed:true});goTask(data.id)}})}
async function deleteSchedule(row){await api.delete(`/mtask/schedules/${row.id}`);await refreshSchedules()}
async function loadTemplates(){const [a,b]=await Promise.all([api.get('/mtask/templates'),api.get('/mtask/templates/categorys')]);templates.value=a.data;categories.value=b.data}
function newTemplate(example=false){templateForm.value={name:example?'服务状态查询':'',cmd:example?'systemctl status {{service}} --no-pager':'',description:example?'只读查询 systemd 服务状态，不会重启服务。':'',category:categories.value[0]?.id,parameters:example?[{name:'service',type:'enum',choiceText:'nginx,sshd',default:'sshd'}]:[]};revisions.value=[];templateOpen.value=true}
async function editTemplate(row){const {data}=await api.get(`/mtask/templates/${row.id}`);templateForm.value={...data.template,parameters:data.template.parameters.map(p=>({...p,choiceText:(p.choices||[]).join(',')}))};revisions.value=data.revisions;templateOpen.value=true}
async function saveTemplate(){saving.value=true;try{const payload={...templateForm.value,parameters:templateForm.value.parameters.map(p=>{const item={name:p.name,type:p.type,required:p.required!==false};if(p.default!==''&&p.default!=null)item.default=p.default;if(p.type==='enum')item.choices=split(p.choiceText);return item}),expected_version:templateForm.value.version};if(payload.id)await api.patch(`/mtask/templates/${payload.id}`,payload);else await api.post('/mtask/templates',payload);templateOpen.value=false;await loadTemplates()}finally{saving.value=false}}
async function createCategory(){if(!categoryName.value.trim())return;await api.post('/mtask/templates/categorys',{name:categoryName.value});categoryName.value='';await loadTemplates()}
function prepareRun(row){runTarget.value=row;runHosts.value=[...selected.value];parameters.value=Object.fromEntries(row.parameters.map(x=>[x.name,x.default??'']));preview.value='';runOpen.value=true}
async function previewCommand(){const {data}=await api.post(`/mtask/templates/${runTarget.value.id}`,{parameters:parameters.value});preview.value=data.command;return data}
async function runTemplate(){if(!runHosts.value.length){message.warning('请选择目标主机');return}const old=preview.value;const rendered=await previewCommand();if(!old||old!==rendered.command){message.info('最终命令已更新，请检查后再次确认提交');return}saving.value=true;try{const {data}=await api.post('/mtask/tasks',{host_ids:runHosts.value,template_id:runTarget.value.id,template_version:runTarget.value.version,parameters:parameters.value,confirmed:true});runOpen.value=false;goTask(data.id)}finally{saving.value=false}}
onMounted(()=>Promise.all([loadHosts(),refreshSchedules(),loadTemplates()]))
</script>
<style scoped>
.toolbar{margin:16px 0}.profiles{display:flex;gap:16px;margin:20px 0}.profiles .ant-card{flex:1;cursor:pointer}.chosen{border-color:var(--accent);background:var(--accent-soft)}.profiles p{color:var(--muted);margin:12px 0 0}.parameter{display:flex;gap:8px;margin-bottom:10px}.evidence{white-space:pre-wrap;word-break:break-word;max-height:300px;overflow:auto;background:var(--surface-alt);padding:16px;margin-top:16px}small{color:var(--muted)}
@media(max-width:650px){.profiles{flex-direction:column;gap:8px}.operations :deep(.ant-form-item .ant-space){max-width:100%}.operations :deep(.ant-space-item){min-width:0;max-width:100%}.operations :deep(.ant-input){max-width:100%}}</style>
